-- Deploy-time catalog sync | catalog_syncs (2026-10-26, N25).
--
-- One append-only row per successful production catalog sync, written last by
-- `pnpm deploy:catalog`. Generated by
-- `prisma migrate diff --from-schema <HEAD schema> --to-schema prisma/schema.prisma`
-- because there is no non-production database and `--from-migrations` needs a
-- shadow DB. The CHECKs below are hand-added (CLAUDE.md §13 — no Prisma
-- equivalent). RLS comes from lib/db/policies.sql, applied by the next build
-- step (`pnpm db:policies`).

-- CreateTable
CREATE TABLE "catalog_syncs" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "hash" TEXT NOT NULL,
    "courses" INTEGER NOT NULL,
    "skills" INTEGER NOT NULL,
    "templates" INTEGER NOT NULL,
    "bundles" INTEGER NOT NULL,
    "git_sha" TEXT,
    "synced_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "catalog_syncs_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "catalog_syncs_synced_at_idx" ON "catalog_syncs"("synced_at");

-- Hand-written below.
ALTER TABLE "catalog_syncs" ADD CONSTRAINT "catalog_syncs_hash_hex" CHECK ("hash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "catalog_syncs" ADD CONSTRAINT "catalog_syncs_courses_nonneg" CHECK ("courses" >= 0);
ALTER TABLE "catalog_syncs" ADD CONSTRAINT "catalog_syncs_skills_nonneg" CHECK ("skills" >= 0);
ALTER TABLE "catalog_syncs" ADD CONSTRAINT "catalog_syncs_templates_nonneg" CHECK ("templates" >= 0);
ALTER TABLE "catalog_syncs" ADD CONSTRAINT "catalog_syncs_bundles_nonneg" CHECK ("bundles" >= 0);
